def decode_escape(s, i):
    c = s[i]
    maps = {'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"',"'":"'"}
    if c in maps: return maps[c], i+1
    if c == 'z':
        i += 1
        while i < len(s) and s[i].isspace(): i += 1
        return '', i
    if c == 'x' and i+2 < len(s):
        hx = s[i+1:i+3]
        try: return chr(int(hx,16)), i+3
        except: return 'x', i+1
    if c == 'u' and i+1 < len(s) and s[i+1] == '{':
        j = s.find('}', i+2)
        if j != -1:
            try: return chr(int(s[i+2:j],16)), j+1
            except: pass
    if c.isdigit():
        j=i; digs=''
        while j<len(s) and len(digs)<3 and s[j].isdigit(): digs+=s[j]; j+=1
        return chr(int(digs)%256), j
    if c == '\n': return '', i+1
    return c, i+1

def read_long(src, i):
    # at '['; return (content, newpos) or None
    j=i+1; eq=0
    while j<len(src) and src[j]=='=': eq+=1; j+=1
    if j>=len(src) or src[j]!='[': return None
    close = ']' + '='*eq + ']'
    start = j+1
    if start < len(src) and src[start] == '\n': start += 1
    k = src.find(close, start)
    if k == -1: raise LuaError('unfinished long string')
    return src[start:k], k+len(close)

def tokenize(src):
    toks=[]; i=0; line=1; col=1
    def add(t,v,l=line,c=col): toks.append(Token(t,v,l,c))
    while i < len(src):
        c=src[i]
        if c in ' \t\r\f\v': i+=1; col+=1; continue
        if c=='\n': i+=1; line+=1; col=1; continue
        if c=='-' and i+1<len(src) and src[i+1]=='-':
            if i+2<len(src) and src[i+2]=='[':
                try:
                    res=read_long(src,i+2)
                except LuaError:
                    res=None
                if res:
                    text, ni=res; line += src[i:ni].count('\n');
                    col = 1 if '\n' in src[i:ni] else col+(ni-i); i=ni; continue
            j=src.find('\n',i)
            if j==-1: break
            i=j; continue
        if c=='[':
            res=read_long(src,i)
            if res:
                text, ni=res; add('string', text); line += src[i:ni].count('\n'); col=1 if '\n' in src[i:ni] else col+(ni-i); i=ni; continue
        if c in ('"',"'"):
