                if c=='\\':
                    val, ni=decode_escape(src,i+1); out+=val
                    seg=src[i:ni]; line+=seg.count('\n'); col = 1 if '\n' in seg else col+(ni-i); i=ni
                else:
                    out+=c
                    if c=='\n': line+=1; col=1
                    else: col+=1
                    i+=1
            else: raise LuaError('unfinished string', line=l)
            add('string', out, l); continue
        if c.isdigit() or (c=='.' and i+1<len(src) and src[i+1].isdigit()):
            l=line; start=i
            if c=='0' and i+1<len(src) and src[i+1] in 'xX':
                i+=2
                while i<len(src) and (src[i].isalnum() or src[i] in '.+-'): i+=1
            else:
                i+=1
                while i<len(src) and (src[i].isalnum() or src[i] in '._+-'):
                    # stop ..
                    if src[i]=='.' and i+1<len(src) and src[i+1]=='.': break
                    i+=1
            s=src[start:i]; col += i-start
            try:
                if s.lower().startswith('0x'):
                    if any(ch in s for ch in '.pP'):
                        val=float.fromhex(s)
                    else: val=int(s,16)
                else:
                    val=float(s) if any(ch in s for ch in '.eE') else int(s)
            except Exception:
                raise LuaError('malformed number', line=l)
            add('number', val, l); continue
        if c.isalpha() or c=='_':
            l=line; start=i; i+=1
            while i<len(src) and (src[i].isalnum() or src[i]=='_'): i+=1
            s=src[start:i]; col += i-start
            add(s if s in KEYWORDS else 'name', s, l); continue
        l=line
        three=src[i:i+3]; two=src[i:i+2]
        if three=='...': add('...', '...', l); i+=3; col+=3; continue
        if two in ('==','~=','<=','>=','//','<<','>>','..','::'):
            add(two,two,l); i+=2; col+=2; continue
        add(c,c,l); i+=1; col+=1
    toks.append(Token('EOF','EOF',line,col))
    return toks

