    def explist(self):
        es=[self.expr()]
        while self.opt(','): es.append(self.expr())
        return es
    PRECS={'or':1,'and':2,'==':3,'~=':3,'<':3,'>':3,'<=':3,'>=':3,'|':4,'~':5,'&':6,'<<':7,'>>':7,'..':8,'+':9,'-':9,'*':10,'/':10,'//':10,'%':10,'^':12}
    RIGHT={'^','..'}
    def expr(self, minp=0):
        t=self.peek()
        if t.type in ('nil','false','true','number','string'):
            self.pop();
            left=Literal(NIL if t.type=='nil' else False if t.type=='false' else True if t.type=='true' else t.val)
        elif self.opt('...'):
