def run_chunk(src, glob, chunkname='(stdin)', args=None):
    body=Parser(src, chunkname).parse()
    env=Env(glob, glob)
    if args is not None: env.define('arg', args)
    try:
        exec_block(body, env)
    except ReturnSignal:
        pass

def error_out(prog, e, chunk=''):
    msg=e.msg if isinstance(e,LuaError) else str(e)
    sys.stderr.write(f"{prog}: {msg}\n")

def usage(prog, bad=None):
    if bad: sys.stderr.write(f"{prog}: unrecognized option '{bad}'\n")
    sys.stderr.write(f"usage: {prog} [options] [script [args]]\nAvailable options are:\n  -e stat   execute string 'stat'\n  -i        enter interactive mode after executing 'script'\n  -l mod    require library 'mod' into global 'mod'\n  -l g=mod  require library 'mod' into global 'g'\n  -v        show version information\n  -E        ignore environment variables\n  -W        turn warnings on\n  --        stop handling options\n  -         stop handling options and execute stdin\n")

def parse_cli(argv):
    opts=[]; i=1; script=None
    while i<len(argv):
        a=argv[i]
        if a=='--': i+=1; break
        if a=='-': script='-'; break
        if not a.startswith('-') or a=='': break
        if a=='-v': opts.append(('v',None)); i+=1
        elif a=='-E': opts.append(('E',None)); i+=1
        elif a=='-W': opts.append(('W',None)); i+=1
        elif a=='-i': opts.append(('i',None)); i+=1
        elif a.startswith('-e'):
            if len(a)>2: opts.append(('e',a[2:])); i+=1
            else:
                if i+1>=len(argv): return None,i,'-e'
                opts.append(('e',argv[i+1])); i+=2
        elif a.startswith('-l'):
            if len(a)>2: opts.append(('l',a[2:])); i+=1
            else:
                if i+1>=len(argv): return None,i,'-l'
                opts.append(('l',argv[i+1])); i+=2
        else: return None,i,a
    if script is None and i<len(argv): script=argv[i]
    return opts,i,None

def make_arg_table(argv, script_index, script):
    t=LuaTable()
    if script is None:
        for idx,a in enumerate(argv): t.set(idx, a)
    else:
        t.set(0, script)
        for j in range(1, script_index): t.set(j-script_index, argv[j])
        for n,a in enumerate(argv[script_index+1:],1): t.set(n,a)
    return t

def repl(glob):
    sys.stdout.write(VERSION_LINE+'\n'); sys.stdout.flush()
    while True:
        try:
            sys.stdout.write('> '); sys.stdout.flush(); line=sys.stdin.readline()
            if not line: break
            if line.startswith('='): line='return '+line[1:]
            try:
                body=Parser(line,'stdin').parse(); env=Env(glob,glob); exec_block(body,env)
            except ReturnSignal as r:
                if r.values: sys.stdout.write('\t'.join(lua_tostring(v) for v in r.values)+'\n')
        except LuaError as e:
            sys.stderr.write(str(e.msg)+'\n')
        except KeyboardInterrupt:
            sys.stderr.write('interrupted!\n')

def main(argv=None):
    argv = sys.argv if argv is None else argv
    prog=argv[0]
    parsed=parse_cli(argv)
    if parsed[0] is None:
        usage(prog, parsed[2]); return 1
    opts, idx, bad=parsed
    interactive=any(o[0]=='i' for o in opts)
    ignore_env=any(o[0]=='E' for o in opts)
    script=None; script_index=idx
    if idx < len(argv): script=argv[idx]
    glob=Env(); install_std(glob)
    argtab=make_arg_table(argv, script_index if script is not None else len(argv), script)
    glob.define('arg', argtab)
    status=0
    try:
        if not ignore_env and os.environ.get('LUA_INIT'):
            init=os.environ['LUA_INIT']
            if init.startswith('@'): run_chunk(open(init[1:]).read(),glob,'@'+init[1:],argtab)
            else: run_chunk(init,glob,'=LUA_INIT',argtab)
        for o,val in opts:
            if o=='v': print(VERSION_LINE)
            elif o=='e': run_chunk(val,glob,'(command line)',argtab)
            elif o=='l':
                if '=' in val: g,m=val.split('=',1)
                else: g=val.split('.')[-1]; m=val
                r=call_lua(glob.get('require'),[m]).values; glob.set(g,r[0] if r else True)
        if script is not None:
            if script=='-': data=sys.stdin.read(); run_chunk(data,glob,'stdin',argtab)
            else: data=open(script).read(); run_chunk(data,glob,'@'+script,argtab)
        elif not opts or not sys.stdin.isatty():
            if not sys.stdin.isatty(): run_chunk(sys.stdin.read(),glob,'stdin',argtab)
            else: interactive=True
    except LuaError as e:
        error_out(prog,e); status=1
    except FileNotFoundError as e:
        sys.stderr.write(f"{prog}: cannot open {script}: No such file or directory\n"); status=1
    if interactive: repl(glob)
    return status

if __name__=='__main__':
    sys.exit(main())
