        self.line = line
        self.where = where

class ReturnSignal(Exception):
    def __init__(self, values): self.values = values
class BreakSignal(Exception): pass

class Multi:
    def __init__(self, values): self.values = list(values)

def is_nil(v): return v is NIL
def truthy(v): return not (v is NIL or v is False)
def first(v):
    if isinstance(v, Multi):
        return v.values[0] if v.values else NIL
    return v

def lua_type(v):
    if v is NIL: return 'nil'
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, (int,float)) and not isinstance(v,bool): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, LuaTable): return 'table'
    if callable_lua(v): return 'function'
    return 'userdata'

def fmt_num(v):
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if math.isnan(v): return 'nan'
    if math.isinf(v): return 'inf' if v > 0 else '-inf'
    # Lua prints integral floats with .0 in many cases
    if v == int(v): return f"{v:.1f}"
    return format(v, '.14g')

def lua_tostring(v):
    if v is NIL: return 'nil'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, (int,float)) and not isinstance(v,bool): return fmt_num(v)
    if isinstance(v, str): return v
    if isinstance(v, LuaTable): return f"table: 0x{id(v):x}"
    if callable_lua(v): return f"function: 0x{id(v):x}"
    return str(v)

def key_id(k):
    if k is NIL: raise LuaError('table index is nil')
    if isinstance(k, bool): return ('boolean', k)
    if isinstance(k, int) and not isinstance(k,bool): return ('number', float(k))
    if isinstance(k, float):
        if math.isnan(k): raise LuaError('table index is NaN')
        return ('number', float(k))
    if isinstance(k, str): return ('string', k)
    return ('object', id(k))

class LuaTable:
    def __init__(self):
        self.map = OrderedDict()
        self.metatable = NIL
    def get(self, k):
        kid = key_id(k)
        if kid in self.map:
            return self.map[kid][1]
        # very small __index support
        mt = self.metatable
        if isinstance(mt, LuaTable):
            idx = mt.rawget('__index')
            if isinstance(idx, LuaTable): return idx.get(k)
            if callable_lua(idx): return call_lua(idx, [self, k]).values[0] if call_lua(idx,[self,k]).values else NIL
        return NIL
    def rawget(self, k):
        return self.map.get(key_id(k), (None, NIL))[1]
    def set(self, k, v):
        kid = key_id(k)
        if v is NIL:
            if kid in self.map: del self.map[kid]
        else:
            self.map[kid] = (k, v)
    def rawset(self, k, v): self.set(k, v); return self
    def length(self):
        n = 0
        while True:
            if self.rawget(n+1) is NIL: return n
            n += 1
    def keys(self): return [kv[0] for kv in self.map.values()]
    def items(self): return [(kv[0], kv[1]) for kv in self.map.values()]

class Env:
    def __init__(self, parent=None, globals_env=None):
        self.parent = parent
        self.vars = {}
        self.globals = globals_env if globals_env is not None else (self if parent is None else parent.globals)
    def define(self, name, val=NIL): self.vars[name] = val
    def get(self, name):
        e = self
        while e is not None:
            if name in e.vars: return e.vars[name]
            e = e.parent
        return NIL
    def find_env(self, name):
        e = self
        while e is not None:
            if name in e.vars: return e
            e = e.parent
        return None
    def set(self, name, val):
        e = self.find_env(name)
        if e is not None: e.vars[name] = val
        else: self.globals.vars[name] = val

# lexer
KEYWORDS = {'and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','true','until','while'}
class Token:
    def __init__(self, typ, val, line, col=0): self.type=typ; self.val=val; self.line=line; self.col=col
    def __repr__(self): return f"Tok({self.type!r},{self.val!r},L{self.line})"

def decode_escape(s, i):
    c = s[i]
    maps = {'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"',"'":"'"}
    if c in maps: return maps[c], i+1
    if c == 'z':
        i += 1
        while i < len(s) and s[i].isspace(): i += 1
        return '', i
    if c == 'x' and i+2 < len(s):
        hx = s[i+1:i+3]
        try: return chr(int(hx,16)), i+3
        except: return 'x', i+1
    if c == 'u' and i+1 < len(s) and s[i+1] == '{':
        j = s.find('}', i+2)
        if j != -1:
            try: return chr(int(s[i+2:j],16)), j+1
            except: pass
    if c.isdigit():
        j=i; digs=''
        while j<len(s) and len(digs)<3 and s[j].isdigit(): digs+=s[j]; j+=1
        return chr(int(digs)%256), j
    if c == '\n': return '', i+1
    return c, i+1

def read_long(src, i):
    # at '['; return (content, newpos) or None
    j=i+1; eq=0
    while j<len(src) and src[j]=='=': eq+=1; j+=1
    if j>=len(src) or src[j]!='[': return None
    close = ']' + '='*eq + ']'
    start = j+1
    if start < len(src) and src[start] == '\n': start += 1
    k = src.find(close, start)
    if k == -1: raise LuaError('unfinished long string')
    return src[start:k], k+len(close)

def tokenize(src):
    toks=[]; i=0; line=1; col=1
    def add(t,v,l=line,c=col): toks.append(Token(t,v,l,c))
    while i < len(src):
        c=src[i]
        if c in ' \t\r\f\v': i+=1; col+=1; continue
        if c=='\n': i+=1; line+=1; col=1; continue
        if c=='-' and i+1<len(src) and src[i+1]=='-':
            if i+2<len(src) and src[i+2]=='[':
                try:
                    res=read_long(src,i+2)
                except LuaError:
                    res=None
                if res:
                    text, ni=res; line += src[i:ni].count('\n');
                    col = 1 if '\n' in src[i:ni] else col+(ni-i); i=ni; continue
            j=src.find('\n',i)
            if j==-1: break
            i=j; continue
        if c=='[':
            res=read_long(src,i)
            if res:
                text, ni=res; add('string', text); line += src[i:ni].count('\n'); col=1 if '\n' in src[i:ni] else col+(ni-i); i=ni; continue
        if c in ('"',"'"):
            quote=c; l=line; i+=1; col+=1; out=''
            while i<len(src):
                c=src[i]
                if c==quote: i+=1; col+=1; break
                if c=='\\':
                    val, ni=decode_escape(src,i+1); out+=val
                    seg=src[i:ni]; line+=seg.count('\n'); col = 1 if '\n' in seg else col+(ni-i); i=ni
                else:
                    out+=c
                    if c=='\n': line+=1; col=1
                    else: col+=1
                    i+=1
            else: raise LuaError('unfinished string', line=l)
            add('string', out, l); continue
        if c.isdigit() or (c=='.' and i+1<len(src) and src[i+1].isdigit()):
            l=line; start=i
            if c=='0' and i+1<len(src) and src[i+1] in 'xX':
                i+=2
                while i<len(src) and (src[i].isalnum() or src[i] in '.+-'): i+=1
            else:
                i+=1
                while i<len(src) and (src[i].isalnum() or src[i] in '._+-'):
                    # stop ..
                    if src[i]=='.' and i+1<len(src) and src[i+1]=='.': break
                    i+=1
            s=src[start:i]; col += i-start
            try:
                if s.lower().startswith('0x'):
                    if any(ch in s for ch in '.pP'):
                        val=float.fromhex(s)
                    else: val=int(s,16)
                else:
                    val=float(s) if any(ch in s for ch in '.eE') else int(s)
            except Exception:
                raise LuaError('malformed number', line=l)
            add('number', val, l); continue
        if c.isalpha() or c=='_':
            l=line; start=i; i+=1
            while i<len(src) and (src[i].isalnum() or src[i]=='_'): i+=1
            s=src[start:i]; col += i-start
            add(s if s in KEYWORDS else 'name', s, l); continue
        l=line
        three=src[i:i+3]; two=src[i:i+2]
        if three=='...': add('...', '...', l); i+=3; col+=3; continue
        if two in ('==','~=','<=','>=','//','<<','>>','..','::'):
            add(two,two,l); i+=2; col+=2; continue
        add(c,c,l); i+=1; col+=1
    toks.append(Token('EOF','EOF',line,col))
    return toks

# AST nodes are small tuples/classes
class Literal: 
    def __init__(self,v): self.v=v
class Var:
    def __init__(self,n): self.n=n
class Vararg: pass
class BinOp:
    def __init__(self,op,a,b): self.op=op; self.a=a; self.b=b
class UnOp:
    def __init__(self,op,a): self.op=op; self.a=a
class Index:
    def __init__(self,obj,key): self.obj=obj; self.key=key
class Call:
    def __init__(self,func,args,method=None): self.func=func; self.args=args; self.method=method
class FunctionExpr:
    def __init__(self,params,vararg,body,line=1): self.params=params; self.vararg=vararg; self.body=body; self.line=line
class TableCtor:
    def __init__(self,fields): self.fields=fields

class Parser:
    def __init__(self, src, chunkname='(chunk)'):
        self.toks=tokenize(src); self.i=0; self.chunkname=chunkname
    def peek(self): return self.toks[self.i]
    def at(self,t): return self.peek().type==t or self.peek().val==t
    def pop(self,t=None):
        tok=self.peek()
        if t is not None and not (tok.type==t or tok.val==t):
            raise LuaError(f"syntax error near '{tok.val}'", line=tok.line, where=self.chunkname)
        self.i+=1; return tok
    def opt(self,t):
        if self.at(t): return self.pop()
        return None
    def parse(self):
        body=self.block({'EOF'})
        self.pop('EOF')
        return body
    def block(self, stops):
        stmts=[]
        while self.peek().type not in stops and self.peek().val not in stops and not self.at('EOF'):
            if self.at('return'):
                stmts.append(self.stat()); self.opt(';'); break
            stmts.append(self.stat())
            while self.opt(';'): pass
        return stmts
    def stat(self):
        tok=self.peek()
        if self.opt(';'): return ('nop',)
        if self.opt('break'): return ('break',)
        if self.opt('do'):
            b=self.block({'end'}); self.pop('end'); return ('do',b)
        if self.opt('while'):
            e=self.expr(); self.pop('do'); b=self.block({'end'}); self.pop('end'); return ('while',e,b)
        if self.opt('repeat'):
            b=self.block({'until'}); self.pop('until'); e=self.expr(); return ('repeat',b,e)
        if self.opt('if'):
            cases=[]; e=self.expr(); self.pop('then'); b=self.block({'elseif','else','end'}); cases.append((e,b))
            while self.opt('elseif'):
                e=self.expr(); self.pop('then'); b=self.block({'elseif','else','end'}); cases.append((e,b))
            elseb=None
            if self.opt('else'): elseb=self.block({'end'})
            self.pop('end'); return ('if',cases,elseb)
        if self.opt('for'):
            name=self.pop('name').val
            if self.opt('='):
                start=self.expr(); self.pop(','); end=self.expr(); step=Literal(1)
                if self.opt(','): step=self.expr()
                self.pop('do'); b=self.block({'end'}); self.pop('end'); return ('fornum',name,start,end,step,b)
            else:
                names=[name]
                while self.opt(','): names.append(self.pop('name').val)
                self.pop('in'); exps=self.explist(); self.pop('do'); b=self.block({'end'}); self.pop('end'); return ('forgen',names,exps,b)
        if self.opt('function'):
            parts=[self.pop('name').val]; method=None
            while self.opt('.'):
                parts.append(self.pop('name').val)
            if self.opt(':'):
                method=self.pop('name').val
            fn=self.funcbody()
            if method:
                fn.params=['self']+fn.params; parts.append(method)
            return ('funcdef',parts,fn)
        if self.opt('local'):
            if self.opt('function'):
                name=self.pop('name').val; fn=self.funcbody(); return ('localfunc',name,fn)
            names=[self.pop('name').val]
            while self.opt(','): names.append(self.pop('name').val)
            exps=[]
            if self.opt('='): exps=self.explist()
            return ('local',names,exps)
        if self.opt('return'):
            exps=[]
            if not (self.at('end') or self.at('else') or self.at('elseif') or self.at('until') or self.at('EOF') or self.at(';')):
                exps=self.explist()
            return ('return',exps)
        if self.opt('::'):
            self.pop('name'); self.pop('::'); return ('nop',)
        if self.opt('goto'):
            self.pop('name'); return ('nop',)
        # assignment or call
        firstexp=self.suffixed()
        if isinstance(firstexp, Call): return ('callstmt', firstexp)
        vars=[firstexp]
        while self.opt(','):
            v=self.suffixed(); vars.append(v)
        self.pop('=')
        exps=self.explist()
        return ('assign',vars,exps)
    def funcbody(self):
        l=self.peek().line; self.pop('('); params=[]; vararg=False
        if not self.at(')'):
            if self.opt('...'): vararg=True
            else:
                params.append(self.pop('name').val)
                while self.opt(','):
                    if self.opt('...'): vararg=True; break
                    params.append(self.pop('name').val)
        self.pop(')'); b=self.block({'end'}); self.pop('end')
        return FunctionExpr(params,vararg,b,l)
    def explist(self):
        es=[self.expr()]
        while self.opt(','): es.append(self.expr())
        return es
    PRECS={'or':1,'and':2,'==':3,'~=':3,'<':3,'>':3,'<=':3,'>=':3,'|':4,'~':5,'&':6,'<<':7,'>>':7,'..':8,'+':9,'-':9,'*':10,'/':10,'//':10,'%':10,'^':12}
    RIGHT={'^','..'}
    def expr(self, minp=0):
        t=self.peek()
        if t.type in ('nil','false','true','number','string'):
            self.pop();
            left=Literal(NIL if t.type=='nil' else False if t.type=='false' else True if t.type=='true' else t.val)
        elif self.opt('...'):
            left=Vararg()
        elif t.type in ('not',) or t.val in ('-','#','~'):
            op=self.pop().val; right=self.expr(11); left=UnOp(op,right)
        elif self.opt('function'):
            left=self.funcbody()
        elif self.at('{'):
            left=self.tablector()
        else:
            left=self.suffixed()
        while True:
            op=self.peek().val
            if op not in self.PRECS: break
            p=self.PRECS[op]
            if p < minp: break
            self.pop()
            right=self.expr(p if op in self.RIGHT else p+1)
            left=BinOp(op,left,right)
        return left
    def suffixed(self):
        if self.opt('('):
            e=self.expr(); self.pop(')'); left=e
        else:
            tok=self.pop('name'); left=Var(tok.val)
        while True:
            if self.opt('.'):
                left=Index(left, Literal(self.pop('name').val))
            elif self.opt('['):
                key=self.expr(); self.pop(']'); left=Index(left,key)
            elif self.at(':'):
                self.pop(':'); m=self.pop('name').val; args=self.args(); left=Call(left,args,method=m)
            elif self.at('(') or self.at('{') or self.peek().type=='string':
                args=self.args(); left=Call(left,args)
            else: break
        return left
    def args(self):
        if self.opt('('):
            if self.opt(')'): return []
            es=self.explist(); self.pop(')'); return es
        if self.at('{'): return [self.tablector()]
        if self.peek().type=='string': return [Literal(self.pop('string').val)]
        raise LuaError('function arguments expected', line=self.peek().line, where=self.chunkname)
    def tablector(self):
        fields=[]; self.pop('{')
        while not self.at('}'):
            if self.at('['):
                self.pop('['); k=self.expr(); self.pop(']'); self.pop('='); v=self.expr(); fields.append(('key',k,v))
            elif self.peek().type=='name' and self.toks[self.i+1].type=='=':
                k=self.pop('name').val; self.pop('='); v=self.expr(); fields.append(('key',Literal(k),v))
            else:
                fields.append(('array', self.expr()))
            if not (self.opt(',') or self.opt(';')): break
        self.pop('}')
        return TableCtor(fields)

class LuaFunction:
    def __init__(self, params, vararg, body, env, name=None):
        self.params=params; self.vararg=vararg; self.body=body; self.env=env; self.name=name
    def __call__(self, args):
        new=Env(self.env, self.env.globals)
        for i,p in enumerate(self.params): new.define(p, args[i] if i < len(args) else NIL)
        new.define('...', Multi(args[len(self.params):] if self.vararg else []))
        try:
            exec_block(self.body, new)
        except ReturnSignal as r:
            return Multi(r.values)
        return Multi([])
class Builtin:
    def __init__(self, func, name=None): self.func=func; self.name=name or getattr(func,'__name__','builtin')
    def __call__(self,args): return Multi(self.func(args) or [])

def callable_lua(v): return isinstance(v,(LuaFunction,Builtin))
def call_lua(fn,args):
    if not callable_lua(fn): raise LuaError(f"attempt to call a {lua_type(fn)} value")
    return fn(args)

def to_number(v):
    if isinstance(v,(int,float)) and not isinstance(v,bool): return v
    if isinstance(v,str):
        try: return int(v,0)
        except: 
            try: return float(v)
            except: pass
    raise LuaError(f"attempt to perform arithmetic on a {lua_type(v)} value")
def to_int(v): return int(to_number(v))

def lua_eq(a,b):
    if a is NIL and b is NIL: return True
    if isinstance(a,(int,float)) and isinstance(b,(int,float)) and not isinstance(a,bool) and not isinstance(b,bool): return float(a)==float(b)
    return a == b

def eval_expr_list(es, env):
    vals=[]
    if not es: return []
    for e in es[:-1]: vals.append(first(eval_expr(e, env)))
    last=eval_expr(es[-1], env)
    if isinstance(last, Multi): vals.extend(last.values)
    else: vals.append(last)
    return vals

def eval_expr(e, env):
    if isinstance(e, Literal): return e.v
    if isinstance(e, Var): return env.get(e.n)
    if isinstance(e, Vararg): return env.get('...') if isinstance(env.get('...'), Multi) else Multi([])
    if isinstance(e, FunctionExpr): return LuaFunction(e.params,e.vararg,e.body,env)
    if isinstance(e, TableCtor):
        t=LuaTable(); arr=1
        for field in e.fields:
            if field[0]=='key':
                k=first(eval_expr(field[1],env)); v=first(eval_expr(field[2],env)); t.set(k,v)
            else:
                v=first(eval_expr(field[1],env)); t.set(arr,v); arr+=1
        return t
    if isinstance(e, Index):
        obj=first(eval_expr(e.obj,env)); key=first(eval_expr(e.key,env))
        if isinstance(obj,LuaTable): return obj.get(key)
        if isinstance(obj,str):
            lib=env.globals.get('string')
            if isinstance(lib,LuaTable): return lib.get(key)
        raise LuaError(f"attempt to index a {lua_type(obj)} value")
    if isinstance(e, Call):
        if e.method is not None:
            obj=first(eval_expr(e.func,env))
            if isinstance(obj,LuaTable): fn=obj.get(e.method)
            elif isinstance(obj,str): fn=env.globals.get('string').get(e.method)
            else: raise LuaError(f"attempt to index a {lua_type(obj)} value")
            args=[obj]+eval_expr_list(e.args,env)
            return call_lua(fn,args)
        fn=first(eval_expr(e.func,env)); args=eval_expr_list(e.args,env); return call_lua(fn,args)
    if isinstance(e, UnOp):
        a=first(eval_expr(e.a,env)); op=e.op
        if op=='not': return not truthy(a)
        if op=='-': return -to_number(a)
        if op=='#':
            if isinstance(a,str): return len(a)
            if isinstance(a,LuaTable): return a.length()
            raise LuaError(f"attempt to get length of a {lua_type(a)} value")
        if op=='~': return ~to_int(a)
    if isinstance(e, BinOp):
        op=e.op
        if op=='and':
            a=first(eval_expr(e.a,env)); return first(eval_expr(e.b,env)) if truthy(a) else a
        if op=='or':
            a=first(eval_expr(e.a,env)); return a if truthy(a) else first(eval_expr(e.b,env))
        a=first(eval_expr(e.a,env)); b=first(eval_expr(e.b,env))
        if op=='+': return to_number(a)+to_number(b)
        if op=='-': return to_number(a)-to_number(b)
        if op=='*': return to_number(a)*to_number(b)
        if op=='/': return to_number(a)/to_number(b)
        if op=='//': return math.floor(to_number(a)/to_number(b))
        if op=='%': return to_number(a)%to_number(b)
        if op=='^': return float(to_number(a))**float(to_number(b))
        if op=='..': return lua_tostring(a)+lua_tostring(b)
        if op=='==': return lua_eq(a,b)
        if op=='~=': return not lua_eq(a,b)
        if op in ('<','>','<=','>='):
            if isinstance(a,(int,float)) and isinstance(b,(int,float)): pass
            elif isinstance(a,str) and isinstance(b,str): pass
            else: raise LuaError(f"attempt to compare {lua_type(a)} with {lua_type(b)}")
            return {'<':a<b,'>':a>b,'<=':a<=b,'>=':a>=b}[op]
        if op=='&': return to_int(a)&to_int(b)
        if op=='|': return to_int(a)|to_int(b)
        if op=='~': return to_int(a)^to_int(b)
        if op=='<<': return to_int(a)<<to_int(b)
        if op=='>>': return to_int(a)>>to_int(b)
    return NIL

def assign_var(v, val, env):
    if isinstance(v, Var): env.set(v.n, val); return
    if isinstance(v, Index):
        obj=first(eval_expr(v.obj,env)); key=first(eval_expr(v.key,env))
        if not isinstance(obj,LuaTable): raise LuaError(f"attempt to index a {lua_type(obj)} value")
        obj.set(key,val); return
    raise LuaError('syntax error')

def exec_block(stmts, env):
    for st in stmts: exec_stat(st, env)

def exec_scoped(stmts, env):
    exec_block(stmts, Env(env, env.globals))

def exec_stat(st, env):
    tag=st[0]
    if tag=='nop': return
    if tag=='break': raise BreakSignal()
